<template>
 <div class="page" v-loading="loading">
  <div class="page-header"><div><div class="page-title">铺位工程资料</div><div class="subtitle">{{meta.stallCode}}　{{meta.stallName||'暂无商户'}}　{{meta.floorCode}}</div></div><div><el-button @click="router.back()">返回</el-button><el-button v-if="canEdit" type="primary" :loading="saving" @click="save">保存资料</el-button></div></div>
  <el-alert title="工程资料独立于铺位、商户和设备绑定信息，保存后不会覆盖原有业务数据。" type="info" :closable="false" show-icon class="notice"/>
  <el-form :model="form" label-position="top" :disabled="!canEdit">
   <el-card><template #header><div class="card-title"><b>供配电</b><el-button v-if="canEdit" type="primary" link @click="addCable">＋ 添加电缆</el-button></div></template>
    <el-alert v-if="!cableSpecs.length" title="尚未配置电缆规格，请先到“基础字典－电缆规格”中维护型号、额定电流和承载功率。" type="warning" :closable="false" show-icon/>
    <div v-for="(c,index) in (form.cables||[])" :key="index" class="cable-row">
     <el-form-item label="电缆型号/规格"><el-select v-model="c.cableSpecificationId" filterable placeholder="请选择电缆规格" @change="refreshCable(c)"><el-option v-for="s in selectableSpecs(c.cableSpecificationId)" :key="s.id" :value="s.id" :disabled="s.status!==1" :label="`${s.cableModel} ${s.specification}${s.status===1?'':'（已停用）'}`"><span>{{s.cableModel}} {{s.specification}}</span><span class="option-param">{{s.ratedCurrentA}}A / {{s.ratedPowerKw}}kW</span></el-option></el-select></el-form-item>
     <div class="cable-param"><span>电缆参数：{{c.ratedCurrentA||0}} A / {{c.ratedPowerKw||0}} kW</span></div>
     <el-form-item label="供电端开关"><el-select v-model="c.powerSwitchSpecificationId" filterable placeholder="请选择匹配开关" @change="refreshSwitch(c)"><el-option v-for="s in switchSpecs" :key="s.id" :value="s.id" :disabled="s.status!==1" :label="`${s.brand||''} ${s.switchModel} ${s.poleCount} ${s.ratedCurrentA}A${s.status===1?'':'（已停用）'}`"/></el-select></el-form-item><div class="switch-param"><span v-if="c.powerSwitchSpecificationId">{{c.switchPoleCount}} · {{c.switchRatedCurrentA}} A<span v-if="c.switchBreakingCapacityKa"> · {{c.switchBreakingCapacityKa}} kA</span></span><el-tag v-if="switchWarning(c)" type="warning">{{switchWarning(c)}}</el-tag><el-tag v-else-if="c.powerSwitchSpecificationId" type="success">容量匹配</el-tag></div><el-form-item label="电表位置"><el-select v-model="c.meterLocationCode" filterable placeholder="请选择电表位置"><el-option v-for="p in meterLocations" :key="p.itemValue" :label="p.itemLabel" :value="p.itemValue" :disabled="p.status!==1"/></el-select></el-form-item><el-button v-if="canEdit" type="danger" link @click="form.cables.splice(index,1)">删除</el-button>
    </div>
    <el-empty v-if="!(form.cables||[]).length" description="暂未添加供配电回路" :image-size="60"/><div class="cable-summary"><span>供配电回路：<b>{{totalCableQuantity}} 套</b></span><span>合计额定电流：<b>{{totalCableCurrent}} A</b></span><span>合计承载功率：<b>{{totalCablePower}} kW</b></span></div>
    <div class="grid electric-extra"><el-form-item label="铺位设计负荷功率（kW）"><el-input-number v-model="form.loadPowerKw" :min="0" :precision="2"/></el-form-item></div>
   </el-card>
   <el-card><template #header><b>给排水</b></template><div class="grid">
    <el-form-item label="是否供水"><el-switch v-model="form.waterSupply"/></el-form-item><template v-if="form.waterSupply"><el-form-item label="水表口径"><el-input v-model="form.waterMeterCaliber" placeholder="例如 DN20"/></el-form-item><el-form-item label="水表安装位置"><el-input v-model="form.waterMeterLocation"/></el-form-item></template>
    <el-form-item label="是否有排水管"><el-switch v-model="form.drainageAvailable"/></el-form-item><template v-if="form.drainageAvailable"><el-form-item label="排水管口径"><el-input v-model="form.drainagePipeCaliber" placeholder="例如 DN100"/></el-form-item><el-form-item label="排水管路编号"><el-input v-model="form.drainagePipelineNo"/></el-form-item></template>
   </div></el-card>
   <el-card><template #header><b>排油烟与新风</b></template><div class="grid">
    <el-form-item label="是否有排油烟管道"><el-switch v-model="form.exhaustDuctAvailable"/></el-form-item><el-form-item v-if="form.exhaustDuctAvailable" label="排油烟管道编号"><el-input v-model="form.exhaustDuctNo"/></el-form-item>
    <el-form-item label="是否有新风管道"><el-switch v-model="form.freshAirDuctAvailable"/></el-form-item><el-form-item v-if="form.freshAirDuctAvailable" label="新风管道编号"><el-input v-model="form.freshAirDuctNo"/></el-form-item>
   </div></el-card>
   <el-card><template #header><b>空调末端</b></template><div class="grid">
    <el-form-item label="空调设备数量"><el-input-number v-model="form.airConditionerQuantity" :min="0"/></el-form-item><el-form-item label="风盘数量（台）"><el-input-number v-model="form.fanCoilQuantity" :min="0"/></el-form-item><el-form-item label="吊柜数量（台）"><el-input-number v-model="form.hangingCabinetQuantity" :min="0"/></el-form-item><el-form-item label="风口数量（个）"><el-input-number v-model="form.airOutletQuantity" :min="0"/></el-form-item><el-form-item class="wide" label="空调设备型号/规格"><el-input v-model="form.airConditionerModel"/></el-form-item>
   </div></el-card>
   <el-card><template #header><b>燃气资料</b></template><div class="grid">
    <el-form-item label="是否具备燃气条件"><el-switch v-model="form.gasConditionAvailable"/></el-form-item>
    <template v-if="form.gasConditionAvailable"><el-form-item label="是否已接通燃气"><el-switch v-model="form.gasConnected"/></el-form-item><el-form-item label="燃气类型"><el-select v-model="form.gasType" clearable><el-option label="天然气" value="NATURAL_GAS"/><el-option label="液化石油气" value="LPG"/><el-option label="其他" value="OTHER"/></el-select></el-form-item><el-form-item label="燃气管道数量"><el-input-number v-model="form.gasPipeQuantity" :min="0"/></el-form-item><el-form-item label="燃气管道口径"><el-input v-model="form.gasPipeCaliber" placeholder="例如 DN25"/></el-form-item><el-form-item label="燃气管道编号"><el-input v-model="form.gasPipelineNo"/></el-form-item><el-form-item label="燃气接口位置"><el-input v-model="form.gasInterfaceLocation"/></el-form-item>
     <template v-if="form.gasConnected"><el-form-item label="燃气表编号"><el-input v-model="form.gasMeterNo"/></el-form-item><el-form-item label="燃气表型号"><el-input v-model="form.gasMeterModel"/></el-form-item><el-form-item label="燃气表安装位置"><el-input v-model="form.gasMeterLocation"/></el-form-item></template>
     <el-form-item label="设计供气量（m³/h）"><el-input-number v-model="form.designGasFlow" :min="0" :precision="3"/></el-form-item><el-form-item label="设计燃气负荷（kW）"><el-input-number v-model="form.designGasLoadKw" :min="0" :precision="2"/></el-form-item><el-form-item label="燃气阀门编号"><el-input v-model="form.gasValveNo"/></el-form-item><el-form-item label="是否安装燃气报警器"><el-switch v-model="form.gasAlarm"/></el-form-item><el-form-item v-if="form.gasAlarm" label="报警器数量"><el-input-number v-model="form.gasAlarmQuantity" :min="0"/></el-form-item><el-form-item label="是否安装自动切断阀"><el-switch v-model="form.autoShutoffValve"/></el-form-item><el-form-item label="是否通过燃气验收"><el-switch v-model="form.gasAccepted"/></el-form-item><template v-if="form.gasAccepted"><el-form-item label="燃气验收日期"><el-date-picker v-model="form.gasAcceptanceDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="验收单位"><el-input v-model="form.gasAcceptanceOrg"/></el-form-item></template></template>
   </div><el-alert v-if="form.gasConditionAvailable&&(!form.gasAlarm||!form.autoShutoffValve)" title="燃气安全设施未完整配置，请核实报警器和自动切断阀。" type="warning" :closable="false" show-icon/></el-card>
   <el-card><template #header><b>备注</b></template><el-input v-model="form.remark" type="textarea" :rows="4" maxlength="1000" show-word-limit/></el-card>
  </el-form>
  <div v-if="canEdit" class="bottom-save"><el-button type="primary" size="large" :loading="saving" @click="save">保存工程资料</el-button></div>
 </div>
</template>
<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import{stallApi}from'@/api/merchant';import{cableSpecificationApi,powerSwitchSpecificationApi,dictionaryApi,type CableSpecification,type PowerSwitchSpecification,type DictionaryItem}from'@/api/system';import{useUserStore}from'@/stores/user';
const defaults={cables:[],loadPowerKw:null,meterLocation:'',waterSupply:false,waterMeterCaliber:'',waterMeterLocation:'',drainageAvailable:false,drainagePipeCaliber:'',drainagePipelineNo:'',exhaustDuctAvailable:false,exhaustDuctNo:'',freshAirDuctAvailable:false,freshAirDuctNo:'',airConditionerQuantity:0,fanCoilQuantity:0,hangingCabinetQuantity:0,airOutletQuantity:0,airConditionerModel:'',gasConditionAvailable:false,gasConnected:false,gasType:'',gasPipeQuantity:0,gasPipeCaliber:'',gasPipelineNo:'',gasInterfaceLocation:'',gasMeterNo:'',gasMeterModel:'',gasMeterLocation:'',designGasFlow:null,designGasLoadKw:null,gasValveNo:'',gasAlarm:false,gasAlarmQuantity:0,autoShutoffValve:false,gasAccepted:false,gasAcceptanceDate:'',gasAcceptanceOrg:'',remark:''};const route=useRoute(),router=useRouter(),user=useUserStore(),loading=ref(false),saving=ref(false),meta=reactive<any>({}),form=reactive<any>({...defaults,cables:[]}),cableSpecs=ref<CableSpecification[]>([]),switchSpecs=ref<PowerSwitchSpecification[]>([]),meterLocations=ref<DictionaryItem[]>([]);const canEdit=computed(()=>user.user?.roles?.some(r=>['SUPER_ADMIN','SYSTEM_ADMIN'].includes(r)));
function selectableSpecs(){return cableSpecs.value}function refreshCable(row:any){const s=cableSpecs.value.find(x=>x.id===row.cableSpecificationId);if(s)Object.assign(row,{specCode:s.specCode,cableModel:s.cableModel,specification:s.specification,ratedCurrentA:s.ratedCurrentA,ratedPowerKw:s.ratedPowerKw})}function refreshSwitch(row:any){const s=switchSpecs.value.find(x=>x.id===row.powerSwitchSpecificationId);if(s)Object.assign(row,{switchSpecCode:s.specCode,switchBrand:s.brand,switchModel:s.switchModel,switchPoleCount:s.poleCount,switchRatedCurrentA:s.ratedCurrentA,switchBreakingCapacityKa:s.breakingCapacityKa,switchType:s.switchType})}function switchWarning(row:any){return row.powerSwitchSpecificationId&&Number(row.switchRatedCurrentA)>Number(row.ratedCurrentA)?'开关额定电流超过电缆载流量':''}function addCable(){if(!form.cables)form.cables=[];form.cables.push({cableSpecificationId:null,ratedCurrentA:0,ratedPowerKw:0,powerSwitchSpecificationId:null,meterLocationCode:''})}const totalCableQuantity=computed(()=>(form.cables||[]).length);const totalCableCurrent=computed(()=>(form.cables||[]).reduce((n:number,c:any)=>n+(Number(c.ratedCurrentA)||0),0).toFixed(2));const totalCablePower=computed(()=>(form.cables||[]).reduce((n:number,c:any)=>n+(Number(c.ratedPowerKw)||0),0).toFixed(2));
async function load(){loading.value=true;try{const [r,s,sw,locations]:any=await Promise.all([stallApi.getEngineering(Number(route.params.id)),cableSpecificationApi.list(false),powerSwitchSpecificationApi.list(false),dictionaryApi.list('METER_LOCATION',false)]);cableSpecs.value=s;switchSpecs.value=sw;meterLocations.value=locations;Object.assign(meta,r);Object.assign(form,defaults,r.profile||{}, {cables:(r.cables||[]).map((x:any)=>({...x}))})}finally{loading.value=false}}async function save(){if((form.cables||[]).some((x:any)=>!x.cableSpecificationId)){ElMessage.warning('请选择完整的电缆型号规格');return}if((form.cables||[]).some((x:any)=>!x.powerSwitchSpecificationId)){ElMessage.warning('每套供配电回路都需要选择供电端开关');return}if((form.cables||[]).some((x:any)=>!x.meterLocationCode)){ElMessage.warning('每套供配电回路都需要选择电表位置');return}saving.value=true;try{await stallApi.saveEngineering(Number(route.params.id),form);ElMessage.success('铺位工程资料已保存');await load()}finally{saving.value=false}}onMounted(load)
</script>
<style scoped>.subtitle{color:#909399;font-size:13px;margin-top:5px}.notice{margin-bottom:14px}.el-card{margin-bottom:14px}.card-title{display:flex;align-items:center;justify-content:space-between}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 16px}.grid .wide{grid-column:span 2}.grid :deep(.el-input-number),.grid :deep(.el-select),.grid :deep(.el-date-editor){width:100%}.cable-row{display:grid;grid-template-columns:minmax(220px,2fr) minmax(145px,1fr) minmax(220px,2fr) minmax(145px,1fr) minmax(180px,1.4fr) 55px;gap:12px;align-items:center;padding:14px 8px;border-bottom:1px solid #ebeef5}.cable-row .el-form-item{margin:0}.cable-row :deep(.el-select),.cable-row :deep(.el-input-number){width:100%}.cable-param,.switch-param{display:flex;flex-direction:column;color:#606266;font-size:13px;gap:4px;align-items:flex-start}.option-param{float:right;color:#909399;margin-left:20px}.cable-summary{display:flex;justify-content:flex-end;gap:28px;background:#f5f7fa;padding:14px;margin-top:12px}.electric-extra{margin-top:18px}.bottom-save{text-align:center;padding:8px 0 24px}.bottom-save .el-button{min-width:220px}@media(max-width:1200px){.cable-row{grid-template-columns:2fr 1fr 2fr 1fr}.cable-row>button{justify-self:start}}@media(max-width:768px){.page-header{align-items:flex-start}.grid{grid-template-columns:1fr}.grid .wide{grid-column:auto}.el-card{border-radius:10px}.cable-row{grid-template-columns:1fr;padding:14px 0}.cable-summary{flex-direction:column;gap:8px}.option-param{display:none}}</style>
